import{_ as e,o as l,c as a,a0 as s}from"./chunks/framework.DQOulFGV.js";const c=JSON.parse('{"title":"第1章 性能优化","description":"","frontmatter":{},"headers":[],"relativePath":"redis/05-operations/chapter-01-performance.md","filePath":"redis/05-operations/chapter-01-performance.md"}'),i={name:"redis/05-operations/chapter-01-performance.md"};function d(n,t,h,r,o,p){return l(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="第1章-性能优化" tabindex="-1">第1章 性能优化 <a class="header-anchor" href="#第1章-性能优化" aria-label="Permalink to &quot;第1章 性能优化&quot;">​</a></h1><blockquote><p>Redis 性能优化不是玄学，而是围绕几个核心维度：慢命令、内存、网络、持久化。本章先建立指标体系，再逐维度讲解优化手段。</p></blockquote><hr><h2 id="_1-1-指标体系" tabindex="-1">1.1 指标体系 <a class="header-anchor" href="#_1-1-指标体系" aria-label="Permalink to &quot;1.1 指标体系&quot;">​</a></h2><p>评估 Redis 性能，先看这几个关键指标：</p><table tabindex="0"><thead><tr><th style="text-align:left;">指标</th><th style="text-align:left;">含义</th><th style="text-align:left;">获取方式</th></tr></thead><tbody><tr><td style="text-align:left;">QPS</td><td style="text-align:left;">每秒处理请求数</td><td style="text-align:left;"><code>INFO stats</code></td></tr><tr><td style="text-align:left;">延迟</td><td style="text-align:left;">单命令响应时间</td><td style="text-align:left;"><code>redis-cli --latency</code></td></tr><tr><td style="text-align:left;">内存</td><td style="text-align:left;">内存使用与碎片</td><td style="text-align:left;"><code>INFO memory</code></td></tr><tr><td style="text-align:left;">命中率</td><td style="text-align:left;">缓存命中比例</td><td style="text-align:left;">计算 keyspace_hits / (hits+misses)</td></tr><tr><td style="text-align:left;">连接数</td><td style="text-align:left;">客户端连接数</td><td style="text-align:left;"><code>INFO clients</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --latency</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 测试延迟</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stat</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 实时统计 QPS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # 查看累计统计</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # 查看内存</span></span></code></pre></div><blockquote><p>优化的第一步是「测量」，先量化当前基线（延迟、QPS、内存），优化后再对比，避免凭感觉优化。</p></blockquote><hr><h2 id="_1-2-慢查询优化" tabindex="-1">1.2 慢查询优化 <a class="header-anchor" href="#_1-2-慢查询优化" aria-label="Permalink to &quot;1.2 慢查询优化&quot;">​</a></h2><p>慢命令是 Redis 单线程模型的头号杀手——一个慢命令会阻塞所有其他请求。</p><h3 id="定位慢查询" tabindex="-1">定位慢查询 <a class="header-anchor" href="#定位慢查询" aria-label="Permalink to &quot;定位慢查询&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SLOWLOG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 查看最近 10 条慢查询</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CONFIG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> slowlog-log-slower-than</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 超过 10ms 记为慢查询</span></span></code></pre></div><h3 id="常见慢命令与替代" tabindex="-1">常见慢命令与替代 <a class="header-anchor" href="#常见慢命令与替代" aria-label="Permalink to &quot;常见慢命令与替代&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">慢命令</th><th style="text-align:left;">问题</th><th style="text-align:left;">替代方案</th></tr></thead><tbody><tr><td style="text-align:left;"><code>KEYS *</code></td><td style="text-align:left;">全量遍历，O(n)，阻塞</td><td style="text-align:left;"><code>SCAN</code> 游标分批遍历</td></tr><tr><td style="text-align:left;"><code>HGETALL</code> 大 Hash</td><td style="text-align:left;">返回全部字段</td><td style="text-align:left;"><code>HSCAN</code> 分批获取</td></tr><tr><td style="text-align:left;"><code>SMEMBERS</code> 大 Set</td><td style="text-align:left;">返回全部元素</td><td style="text-align:left;"><code>SSCAN</code> 分批获取</td></tr><tr><td style="text-align:left;"><code>DEL</code> 大 Key</td><td style="text-align:left;">同步删除阻塞</td><td style="text-align:left;"><code>UNLINK</code> 异步删除</td></tr><tr><td style="text-align:left;"><code>FLUSHALL</code></td><td style="text-align:left;">清空全部数据</td><td style="text-align:left;">避免在生产环境使用</td></tr></tbody></table><blockquote><p><code>SCAN</code> 系列基于游标分批遍历，不会一次性阻塞主线程，是 <code>KEYS</code>、<code>HGETALL</code> 等全量命令的安全替代。</p></blockquote><hr><h2 id="_1-3-内存优化" tabindex="-1">1.3 内存优化 <a class="header-anchor" href="#_1-3-内存优化" aria-label="Permalink to &quot;1.3 内存优化&quot;">​</a></h2><p>内存优化从「选对结构」「控制规模」「合理过期」三方面入手。</p><table tabindex="0"><thead><tr><th style="text-align:left;">手段</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">选对结构</td><td style="text-align:left;">对象用 Hash 而非 String 存 JSON（见第一卷）</td></tr><tr><td style="text-align:left;">控制编码</td><td style="text-align:left;">小数据用紧凑编码，避免触发升级</td></tr><tr><td style="text-align:left;">设置 TTL</td><td style="text-align:left;">无过期时间的 key 会永久占内存</td></tr><tr><td style="text-align:left;">TTL 随机</td><td style="text-align:left;">避免同时过期引发雪崩（见第三卷）</td></tr><tr><td style="text-align:left;">淘汰策略</td><td style="text-align:left;">设置 maxmemory + 合适淘汰策略</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CONFIG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maxmemory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 4gb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CONFIG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maxmemory-policy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allkeys-lru</span></span></code></pre></div><hr><h2 id="_1-4-网络优化" tabindex="-1">1.4 网络优化 <a class="header-anchor" href="#_1-4-网络优化" aria-label="Permalink to &quot;1.4 网络优化&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">手段</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">Pipeline</td><td style="text-align:left;">批量命令，减少网络往返（见第四卷）</td></tr><tr><td style="text-align:left;">避免大 Key</td><td style="text-align:left;">大 Key 占用带宽，拖慢传输</td></tr><tr><td style="text-align:left;">连接池</td><td style="text-align:left;">复用连接，避免频繁建连/断连</td></tr><tr><td style="text-align:left;">长连接</td><td style="text-align:left;">避免短连接反复 TCP 握手</td></tr></tbody></table><hr><h2 id="_1-5-持久化对性能的影响" tabindex="-1">1.5 持久化对性能的影响 <a class="header-anchor" href="#_1-5-持久化对性能的影响" aria-label="Permalink to &quot;1.5 持久化对性能的影响&quot;">​</a></h2><p>持久化会消耗 CPU 和磁盘 IO，需要合理配置：</p><table tabindex="0"><thead><tr><th style="text-align:left;">配置</th><th style="text-align:left;">影响</th><th style="text-align:left;">建议</th></tr></thead><tbody><tr><td style="text-align:left;"><code>appendfsync always</code></td><td style="text-align:left;">每条命令刷盘，性能最差</td><td style="text-align:left;">除非强一致，否则不用</td></tr><tr><td style="text-align:left;"><code>appendfsync everysec</code></td><td style="text-align:left;">每秒刷盘，性能较好</td><td style="text-align:left;">生产推荐</td></tr><tr><td style="text-align:left;">频繁 BGSAVE</td><td style="text-align:left;">fork 停顿</td><td style="text-align:left;">控制 save 触发频率</td></tr><tr><td style="text-align:left;">大内存 fork</td><td style="text-align:left;">fork 耗时增加</td><td style="text-align:left;">大内存实例关注 fork 停顿</td></tr></tbody></table><blockquote><p>持久化的性能影响主要来自两个点：fsync 刷盘的磁盘 IO，以及 fork 子进程的 CPU 与内存开销。性能敏感场景要重点评估这两点。</p></blockquote>`,29)])])}const g=e(i,[["render",d]]);export{c as __pageData,g as default};
